public class OddEvenPrinter {
    private int number = 1;
    private final int limit = 10;

    synchronized void print(boolean odd) {
        while (number <= limit) {
            while (number <= limit && (number % 2 == 1) != odd) {
                try { wait(); }
                catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                    return;
                }
            }
            if (number <= limit) {
                System.out.println(Thread.currentThread().getName() + ": " + number++);
                notifyAll();
            }
        }
        notifyAll();
    }
    public static void main(String[] args) throws InterruptedException {
        OddEvenPrinter p = new OddEvenPrinter();
        Thread odd = new Thread(() -> p.print(true), "Odd");
        Thread even = new Thread(() -> p.print(false), "Even");
        odd.start(); even.start();
        odd.join(); even.join();
    }
}

