public class ParallelSum {
    static long sum(int[] a, int start, int end) {
        long total = 0;
        for (int i = start; i < end; i++) total += a[i];
        return total;
    }
    public static void main(String[] args) throws Exception {
        int[] a = new int[1000];
        Arrays.fill(a, 1);
        int workers = 4, chunk = (a.length + workers - 1) / workers;
        ExecutorService pool = Executors.newFixedThreadPool(workers);
        try {
            List<Future<Long>> futures = new ArrayList<>();
            for (int i = 0; i < a.length; i += chunk) {
                int start = i, end = Math.min(i + chunk, a.length);
                futures.add(pool.submit(() -> sum(a, start, end)));
            }
            long total = 0;
            for (Future<Long> f : futures) total += f.get();
            System.out.println(total); // 1000
        } finally { pool.shutdown(); }
    }
}

import java.util.concurrent.*;

public class ForkJoinSum extends RecursiveTask<Long> {
    private final int[] values;
    private final int start, end;
    private static final int THRESHOLD = 100;

    ForkJoinSum(int[] values, int start, int end) {
        this.values = values; this.start = start; this.end = end;
    }
    @Override protected Long compute() {
        if (end - start <= THRESHOLD) {
            long sum = 0;
            for (int i = start; i < end; i++) sum += values[i];
            return sum;
        }
        int mid = (start + end) / 2;
        ForkJoinSum left = new ForkJoinSum(values, start, mid);
        ForkJoinSum right = new ForkJoinSum(values, mid, end);
        left.fork();
        long rightResult = right.compute();
        return left.join() + rightResult;
    }
    public static void main(String[] args) {
        int[] a = new int[1000];
        java.util.Arrays.fill(a, 1);
        System.out.println(ForkJoinPool.commonPool().invoke(new ForkJoinSum(a, 0, a.length)));
    }
}

